	private static class PhysicalInputVisitor extends AbstractQueryModelVisitor<RuntimeException> {

		private int position;
		private List<PhysicalInputContract> contracts = List.of();

		protected final void captureNode(QueryModelNode node) {
			int ordinal = position++;
			Set<String> names = node instanceof Filter filter ? filter.getRequiredInputBindingNames() : Set.of();
			boolean independent = node.isIndependentInputScope();
			boolean inherited = node instanceof StatementPattern statement
					&& statement.isContextBindingOriginInherited();
			long rawKinds = node instanceof StatementPattern statement
					? LmdbValueIdFilter.fromStatementPattern(statement).semanticKindWord()
					: 0L;
			if (!names.isEmpty() || independent || inherited || rawKinds != 0L) {
				if (contracts.isEmpty()) {
					contracts = new ArrayList<>();
				}
				contracts.add(new PhysicalInputContract(ordinal, Set.copyOf(names), independent, inherited, rawKinds));
			}
		}

		@Override
		protected void meetNode(QueryModelNode node) {
			captureNode(node);
			super.meetNode(node);
		}

		final List<PhysicalInputContract> snapshot() {
			return List.copyOf(contracts);
		}
	}

	private static final class StructuralHashVisitor extends PhysicalInputVisitor {

		private int hash = 1;
		private boolean hasUnknownBindingSource;

		@Override
		protected void meetNode(QueryModelNode node) {
			captureNode(node);
			hash = hashStep(hash, node.getClass().getName());
			hash = hashStep(hash, node.isIndependentInputScope());
			if (node instanceof StatementPattern statement) {
				hash = hashStep(hash, statement.isContextBindingOriginInherited());
				hash = hashStep(hash, LmdbValueIdFilter.fromStatementPattern(statement).semanticKindWord());
			}
			if (node instanceof Var var) {
				hash = hashStep(hash, var.getName());
				hash = hashStep(hash, var.isAnonymous());
				hash = hashStep(hash, var.isConstant());
				hash = hashStep(hash, valueFingerprint(var.getValue()));
			} else if (node instanceof ValueConstant constant) {
				hash = hashStep(hash, valueFingerprint(constant.getValue()));
			} else if (node instanceof BindingSetAssignment assignment) {
				hasUnknownBindingSource |= assignment.getBindingSets() != null
						&& !assignment.hasRepeatableBindingSets();
				hash = hashStep(hash, BindingSetAssignmentFactorFingerprint.of(assignment));
			} else if (node instanceof Filter filter) {
				hash = hashStep(hash, filter.getRequiredInputBindingNames());
			}
			node.visitChildren(this);
			hash = hashStep(hash, "end");
		}

		private int hash() {
			return hash;
		}
	}

	private static final class RetainedBytesVisitor extends AbstractQueryModelVisitor<RuntimeException> {

		private final boolean includeProviderPayload;

		RetainedBytesVisitor() {
			this(true);
		}

		RetainedBytesVisitor(boolean includeProviderPayload) {
			this.includeProviderPayload = includeProviderPayload;
		}

		private long retainedBytes = 256L;
		private final ProviderRetainedMemory providerMemory = new ProviderRetainedMemory();

		@Override
		protected void meetNode(QueryModelNode node) {
			if (includeProviderPayload) {
				providerMemory.account(node.getRuntimeFeedbackContract());
			}
			retainedBytes = saturatedAdd(retainedBytes,
					saturatedAdd(192L, stringBytes(node.getClass().getName())));
			if (node instanceof Var var) {
				retainedBytes = saturatedAdd(retainedBytes, stringBytes(var.getName()));
				if (var.getValue() != null) {
					retainedBytes = saturatedAdd(retainedBytes, 256L);
				}
			} else if (node instanceof ValueConstant constant && constant.getValue() != null) {
				retainedBytes = saturatedAdd(retainedBytes, 256L);
			} else if (node instanceof BindingSetAssignment assignment) {
				for (String bindingName : assignment.getBindingNames()) {
					retainedBytes = saturatedAdd(retainedBytes, stringBytes(bindingName));
				}
				Iterable<BindingSet> bindingSets = assignment.getBindingSets();
				if (bindingSets != null && !assignment.hasRepeatableBindingSets()) {
					// An opaque retained source has no measurable row bound and cannot fit a bounded persistent cache.
					retainedBytes = Long.MAX_VALUE;
					return;
				}
				if (bindingSets != null) {
					for (BindingSet bindingSet : bindingSets) {
						retainedBytes = saturatedAdd(retainedBytes, 128L);
						retainedBytes = saturatedAdd(retainedBytes, 256L * bindingSet.size());
					}
				}
			} else if (node instanceof Filter filter && !filter.getRequiredInputBindingNames().isEmpty()) {
				retainedBytes = saturatedAdd(retainedBytes, 64L + 32L * filter.getRequiredInputBindingNames().size());
				for (String name : filter.getRequiredInputBindingNames()) {
					retainedBytes = saturatedAdd(retainedBytes, stringBytes(name));
				}
			}
			super.meetNode(node);
		}

		private long retainedBytes() {
			return saturatedAdd(retainedBytes, providerMemory.bytes());
		}
	}

	private record FallbackFactorFingerprint(int hash, String type, String tree,
			List<PhysicalInputContract> physicalInputs) {

		private static FallbackFactorFingerprint of(QueryModelNode node) {
			String type = node == null ? "null" : node.getClass().getName();
			String tree = node == null ? "" : node.toString();
			PhysicalInputVisitor visitor = new PhysicalInputVisitor();
			if (node != null) {
				node.visit(visitor);
			}
			List<PhysicalInputContract> inputs = visitor.snapshot();
			int hash = nullableHash(type);
			hash = hashStep(hash, tree);
			hash = hashStep(hash, inputs);
			return new FallbackFactorFingerprint(hash, type, tree, inputs);
		}

		@Override
		public int hashCode() {
			return hash;
		}
	}
